import time

from taf.internal.sbts.admin.exceptions import AdminApiProcedureFailureException

from taf.rfrl.l3_call.logger.l3_call_logger import log_input_and_output, log_to_console
from taf.rfrl.l3_call.cell.cell_factory import CellFactory
from taf.rfrl.l3_call.delta.delta_factory import DeltaOperatorFactory


class Env(object):
    __MISSING_IMPLEMENTATION_ERROR_MSG = "{} class has missing implementation of {} method"

    def __init__(self):
        self.called_cells_distnames = None
        self.ignored_cells_distnames = []
        self._cell_ids = None
        self._verification_msgs = {}
        self._cell = None
        self._called_cells = []
        self._delta = None
        self._called_cell_spectrum = None
        self._not_called_cells_distnames = []
        self._pcap = None
        self._called_cell_spectrum = None
        self._ran = None

    @property
    def cell_ids(self):
        """
        Returns cell IDs of called cells
        (in case of LTE cell this is eutranCellId, in case of NR cell nrCellIdentity).
        """
        if not self._cell_ids:
            self._cell_ids = self._get_cell_ids()

        return self._cell_ids

    def prepare_setup_to_call(self):
        """
        Prepares environment to call in particular blocks certain cells and
        changes cellBarred parameter to adequate values.
        """
        self._prepare_setup_to_call()

    def clean_up_after_call(self, close_connection_to_bts=True):
        """
        Returns environment to the state from before the test
        :param close_connection_to_bts: if True, closes connection to BTS
        :type close_connection_to_bts: bool
        """
        self._clean_up_after_call(close_connection_to_bts=close_connection_to_bts)

    def is_callable(self, cell_distname):
        """
        Checks whether environment is callable e.g. if technology of cell with cell_distname is currently
        handled by the library
        :param cell_distname: configuration distname of checked cell
        :type cell_distname: str

        :returns: True if cell is callable, False if it is not callable
        :rtype: bool
        :raises: InvalidCellType when technology of called cell is not yet handled
        by the library
        """
        return self._is_callable(cell_distname=cell_distname)

    def get_number_of_super_subcells(self, cell_distname):
        """
        Returns number of super subcells for given supercell
        """
        return self._get_number_of_super_subcells(cell_distname=cell_distname)

    def verify_pcap(self, cell_distname, pcap_path, attach_should_be_possible=True):
        """
        Verifies PCAP file after attach procedure
        :param cell_distname: distname of called cell
        :type cell_distname: str
        :param pcap_path: path to PCAP file
        :type pcap_path: str
        :param attach_should_be_possible: if attach was expected to be possible,
                                          defaults to True
        :type attach_should_be_possible: bool
        """
        self._verify_pcap(cell_distname=cell_distname, pcap_path=pcap_path,
                          attach_should_be_possible=attach_should_be_possible)

    def verify_pcap_after_parallel_call(self, cell_distname, pcap_path, number_of_expected_attach_msgs):
        """
        Verifies PCAP file after parallel attach procedure
        :param cell_distname: distname of called cell
        :type cell_distname: str
        :param pcap_path: path to PCAP file
        :type pcap_path: str
        :param number_of_expected_attach_msgs: number of expected attach messages
        :type number_of_expected_attach_msgs: int
        """
        self._verify_pcap_after_parallel_call(cell_distname=cell_distname, pcap_path=pcap_path,
                                              number_of_expected_attach_msgs=number_of_expected_attach_msgs)

    def make_selected_cells_unbarred(self, cells_distnames):
        """
        Changes cellBarred parameter to notBarred
        for cells with cell_distnames
        """
        self._make_selected_cells_unbarred(cells_distnames=cells_distnames)

    def make_selected_cells_barred(self, cells_distnames):
        """
        Changes cellBarred parameter to barred
        for cells with cell_distnames
        """
        self._make_selected_cells_barred(cells_distnames=cells_distnames)

    def open_api_connection(self):
        """
        Opens OAM http connection to BTS
        """
        self._open_api_connection()

    def handle_beamforming(self):
        """
        If beamforming is activated, waits for beam to form
        """
        if self._cell.is_beamforming_activated():
            delay = self._cell.beamforming_delay
            log_to_console("Waiting {} seconds for beamforming to be ready".format(delay))
            time.sleep(delay)

    @log_input_and_output
    def _is_spectrum_shared(self, cell_spectrum_1, cell_spectrum_2):
        """
        Compares two cell spectra and returns bool value informing whether
        spectra overlap
        :param cell_spectrum_1: first spectrum given by a list, where cell_spectrum_1[0] is a lower
        frequency limit and cell_spectrum_1[1] is an upper frequency limit
        :type cell_spectrum_1: list(float)
        :param cell_spectrum_2: second spectrum given by a list, where cell_spectrum_2[0] is a lower
        frequency limit and cell_spectrum_2[1] is an upper frequency limit
        :type cell_spectrum_2: list(float)

        :return: True if two spectra overlap, False if they do not overlap
        :rtype: bool
        """
        return cell_spectrum_1[0] <= cell_spectrum_2[1] and cell_spectrum_2[0] <= cell_spectrum_1[1]

    def _get_cell_ids(self):
        """
        Gets IDs of cells given by called_cells_distnames
        (in case of LTE cell this is eutranCellId, in case of NR cell nrCellIdentity).

        :returns: ID of called cell, single ID in SA mode e.g. {"gnb_cell": 1234},
        gnb and enb cell in NSA mode e.g. {"gnb_cell": 213, "enb_cell": 456}
        :rtype: dict
        """
        cell_ids = {}
        for called_cell_distname in self.called_cells_distnames:
            cell_ids[called_cell_distname] = self._get_cell_id(called_cell_distname=called_cell_distname)

        return cell_ids

    def _create_cell(self, cell_distname, bts_connection_alias, shared_spectrum=False):
        return CellFactory.create_cell(ran=self._ran, cell_distname=cell_distname,
                                       shared_spectrum=shared_spectrum,
                                       bts_connection_alias=bts_connection_alias)

    def _handle_dss(self):
        if self._cell.is_dss():
            self._cell.dss_pair = self._cell.get_dss_pair()
            log_to_console("Called cell is in DSS mode! Its DSS pair: {} "
                           "will not be barred/blocked!".format(self._cell.dss_pair))

    @staticmethod
    def _perform_delta_recommissioning(delta, delay=0):
        if not delta.is_empty():
            log_to_console("Performing delta recommissioning to change cellBarred parameter value for cell(s)")
            for _ in range(4):
                try:
                    delta.perform_delta_recommissioning(skip_parameter_relation_errors=True)
                    time.sleep(delay)   # reason: SISOCRT-2536
                    break
                except AdminApiProcedureFailureException as e:
                    log_to_console("Failed to perform delta recommissioning to change cellBarred "
                                   "parameter value for cell(s) with error: {} \n !!TRYING AGAIN!!".format(e))
                    time.sleep(60)  # reason: SISOCRT-2441
            delta.remove_delta()

    def _create_delta(self, connection_alias, id):
        return DeltaOperatorFactory.create_delta_operator(ran=self._ran,
                                                          connection_alias=connection_alias,
                                                          delta_id=id)

    def _get_cell_id(self, called_cell_distname):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._get_cell_id.__name__))

    def _clean_up_after_call(self, close_connection_to_bts):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._clean_up_after_call.__name__))

    def _open_api_connection(self):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._open_api_connection.__name__))

    def _is_callable(self, cell_distname):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._is_callable.__name__))

    def _get_number_of_super_subcells(self, cell_distname):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._get_number_of_super_subcells.__name__))

    def _make_selected_cells_unbarred(self, cells_distnames):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._make_selected_cells_unbarred.__name__))

    def _make_selected_cells_barred(self, cells_distnames):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._make_selected_cells_barred.__name__))

    def _prepare_setup_to_call(self):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._prepare_setup_to_call.__name__))

    def _verify_pcap(self, cell_distname, pcap_path, attach_should_be_possible):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._verify_pcap.__name__))

    def _verify_pcap_after_parallel_call(self, cell_distname, pcap_path, number_of_expected_attach_msgs):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._verify_pcap_after_parallel_call.__name__))
